const KEY='moa-operations-demo-v2';
const today=()=>new Date().toLocaleDateString('en-CA');
const addDays=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('ko-KR')};
const seed=()=>({folders:[{id:'f1',name:'캡스톤 자료',rule:'캡스톤 회의, 아이디어, 발표 및 실험 자료를 보관합니다.'},{id:'f2',name:'공모전',rule:'공모전 안내, 지원 서류, 제출물과 결과 자료를 보관합니다.'},{id:'f3',name:'영수증 · 증빙',rule:'결제 영수증과 신청 확인서 등 증빙을 보관합니다.'}],files:[{id:'a1',name:'캡스톤 발표 구성안.md',kind:'MD',source:'MacBook · 다운로드',folder:'캡스톤 자료',reason:'발표 목차와 캡스톤 프로젝트명이 일치합니다.',date:today()},{id:'a2',name:'공모전_신청서.pdf',kind:'PDF',source:'iPad · 동기화 폴더',folder:'공모전',reason:'공모전 폴더 지침과 파일명이 일치합니다.',date:today()},{id:'a3',name:'결제 영수증 11월.png',kind:'PNG',source:'iPhone · 예시 파일',folder:'영수증 · 증빙',reason:'영수증 관련 문구가 확인됩니다.',date:today()},{id:'a4',name:'캡스톤 회의록.pdf',kind:'PDF',source:'MacBook · 다운로드',folder:'기타',reason:'회의록의 주제가 여러 프로젝트와 겹칩니다.',date:today()},{id:'a5',name:'화이트보드 스크린샷.png',kind:'PNG',source:'iPhone · 예시 파일',folder:'기타',reason:'이미지 속 문맥만으로 프로젝트를 확정하기 어렵습니다.',date:today()},{id:'a6',name:'아이디어 메모.md',kind:'MD',source:'iPad · 예시 파일',folder:'기타',reason:'기존 폴더 지침과 일치하는 항목이 없습니다.',date:today()},{id:'a7',name:'모델 실험 로그.csv',kind:'CSV',source:'MacBook · 다운로드',folder:'캡스톤 자료',reason:'실험 프로젝트 이름이 지침과 일치합니다.',date:today()}],journal:[],settings:{screenshot:'ask',deletion:30,interval:'manual'}});
function migrateOld(){try{const old=JSON.parse(localStorage.getItem('moa-draft-v1'));if(!old||!Array.isArray(old.files)||!Array.isArray(old.folders))return null;return {folders:old.folders.filter(f=>f.name!=='기타').map((f,i)=>({id:`legacy-${i}`,name:f.name,rule:f.rule||''})),files:old.files.map((f,i)=>({id:`legacy-file-${i}`,name:f.name,kind:(f.name.split('.').pop()||'FILE').toUpperCase(),source:f.source||'예시 파일',folder:f.folder||'기타',reason:f.reason||'이전 데모 데이터',date:today()})),journal:[],settings:{screenshot:'ask',deletion:30,interval:old.settings?.interval||'manual'}}}catch{return null}}
let state;try{const old=JSON.parse(localStorage.getItem(KEY));state=old&&Array.isArray(old.files)&&Array.isArray(old.folders)?old:(migrateOld()||seed())}catch{state=migrateOld()||seed()}
let activeFolder=state.folders[0]?.id;let fileFilter='all';let pendingAction=null;let lastFocus=null;
const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const pending=()=>state.files.filter(f=>f.folder==='기타'&&!f.deleted&&!f.deleteAt);
const countFolder=n=>state.files.filter(f=>f.folder===n&&!f.deleted&&!f.deleteAt).length;
const fileRow=f=>`<div class="file-row"><div class="file-icon">${escapeHTML(f.kind)}</div><div class="file-main"><b>${escapeHTML(f.name)}</b><small>${escapeHTML(f.source)} · ${escapeHTML(f.reason)}</small></div><div class="file-meta"><span class="chip ${f.deleted||f.deleteAt?'trash':f.folder==='기타'?'other':''}">${escapeHTML(f.deleted?'삭제 완료':f.deleteAt?'삭제 예정':f.folder)}</span><small>${escapeHTML(f.deleteAt||f.date||'')}</small></div></div>`;
const empty=s=>`<div class="empty">${escapeHTML(s)}</div>`;
function page(name){if(!document.getElementById(name)?.classList.contains('page'))return;closeMenu();document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===name));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===name));history.replaceState(null,'','#'+name);window.scrollTo({top:0,behavior:'instant'});render();document.dispatchEvent(new Event('moa-page'))}
function closeMenu(){ $('#mobile-menu').hidden=true;$('#menu-backdrop').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','메뉴 열기')}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#mobile-menu').hidden;$('#mobile-menu').hidden=!open;$('#menu-backdrop').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기')});$('#menu-backdrop').addEventListener('click',closeMenu);
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)page(b.dataset.page)});
function render(){if(window.MoaLive?.enabled){window.MoaLive.render();return;}const p=pending();$('#nav-pending').textContent=p.length;$('#stat-pending').textContent=p.length;$('#stat-folders').textContent=state.folders.length;$('#stat-today').textContent=state.files.filter(f=>f.date===today()&&f.folder!=='기타'&&!f.deleted&&!f.deleteAt).length;$('#review-count').textContent=`${p.length}개 대기`;const recent=state.files.filter(f=>!f.deleted&&!f.deleteAt).slice(0,5);$('#recent-files').innerHTML=recent.length?recent.map(fileRow).join(''):empty('최근 파일이 없습니다.');$('#pending-summary').innerHTML=p.length?`<strong>${p.length}개 파일에 결정이 필요합니다.</strong><p>각 파일의 근거를 보고 기존 폴더, 새 폴더 또는 삭제를 선택하세요.</p><button class="primary" data-page="review">분류 대기 보기 ↗</button>`:`<strong>확인할 파일이 없습니다.</strong><p>새로 판단이 필요한 파일이 생기면 이곳에 표시됩니다.</p>`;$('#folder-summary').innerHTML=state.folders.map(f=>`<div class="folder-summary-row"><b>${escapeHTML(f.name)}</b><span>${countFolder(f.name)}개</span></div>`).join('');renderFiles();renderFolders();renderReview();renderTrash();renderSettings()}
function renderFiles(){if(window.MoaLive?.enabled){window.MoaLive.render();return;}const q=$('#file-search').value.trim().toLowerCase();const list=state.files.filter(f=>!f.deleted&&!f.deleteAt&&(fileFilter==='all'||(fileFilter==='other'?f.folder==='기타':f.folder!=='기타'))&&(!q||`${f.name} ${f.folder}`.toLowerCase().includes(q)));$('#all-files').innerHTML=list.length?list.map(fileRow).join(''):empty('조건에 맞는 파일이 없습니다.')}
$('#file-search').addEventListener('input',renderFiles);$('#file-filter').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;fileFilter=b.dataset.filter;$('#file-filter').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));renderFiles()});
function renderFolders(){if(window.MoaLive?.enabled){window.MoaLive.selectFolder(activeFolder);return;}if(!state.folders.some(f=>f.id===activeFolder))activeFolder=state.folders[0]?.id;$('#folder-list').innerHTML=state.folders.map(f=>`<button class="${f.id===activeFolder?'active':''}" data-folder="${escapeHTML(f.id)}"><span>${escapeHTML(f.name)}</span><small>${countFolder(f.name)}개</small></button>`).join('');const f=state.folders.find(x=>x.id===activeFolder);if(!f){$('#folder-detail').innerHTML=empty('폴더가 없습니다.');return}const list=state.files.filter(x=>x.folder===f.name&&!x.deleted&&!x.deleteAt);$('#folder-detail').innerHTML=`<h2>${escapeHTML(f.name)}</h2><p>폴더 지침 · <code>_project.md</code> 시연 내용</p><label class="sr-only" for="folder-rule">폴더 지침</label><textarea id="folder-rule">${escapeHTML(f.rule)}</textarea><div class="actions"><button class="primary" id="save-rule">지침 저장</button></div><h3>이 폴더의 파일 · ${list.length}개</h3><div class="file-stack">${list.length?list.map(fileRow).join(''):empty('이 폴더에는 파일이 없습니다.')}</div>`}
$('#folder-list').addEventListener('click',e=>{const b=e.target.closest('[data-folder]');if(!b)return;activeFolder=b.dataset.folder;renderFolders()});$('#folder-detail').addEventListener('click',e=>{if(e.target.id!=='save-rule')return;const f=state.folders.find(x=>x.id===activeFolder);const value=$('#folder-rule').value.trim();if(!f||!value){alert('지침을 입력해 주세요.');return}if(value===f.rule)return;const before=snapshot();f.rule=value;record('폴더 지침 수정',`${f.name} · _project.md`,before);render()});
function reviewCard(f){const options=state.folders.map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.name)}</option>`).join('');return `<article class="review-card" data-file="${escapeHTML(f.id)}"><div class="review-card-header"><h2>${escapeHTML(f.name)}</h2><span class="chip other">판단 대기</span></div><p>${escapeHTML(f.source)}</p><p class="reason"><b>대기 이유</b> · ${escapeHTML(f.reason)}</p><div class="preview"><b>파일 미리보기</b><br>이 데모에는 실제 파일 본문이 연결되지 않았습니다. 파일명과 분류 근거를 확인해 주세요.</div><div class="review-controls"><label>처리 방법<select class="decision"><option value="existing">기존 폴더로</option><option value="new">새 폴더 만들기</option><option value="delete">삭제 예정으로</option></select></label><label class="destination-label">대상 폴더<select class="destination">${options}</select></label><label class="new-name-label" hidden>새 폴더 이름<input class="new-name" maxlength="60" placeholder="예: 연구 자료"></label><label class="new-rule-label" hidden>폴더 지침<input class="new-rule" maxlength="300" placeholder="어떤 파일을 보관할지 설명"></label><button class="primary propose">내용 확인</button></div></article>`}
function renderReview(){$('#review-list').innerHTML=pending().length?pending().map(reviewCard).join(''):empty('분류를 기다리는 파일이 없습니다.')}$('#review-list').addEventListener('change',e=>{if(!e.target.classList.contains('decision'))return;const c=e.target.closest('.review-card');const kind=e.target.value;c.querySelector('.destination-label').hidden=kind!=='existing';c.querySelector('.new-name-label').hidden=kind!=='new';c.querySelector('.new-rule-label').hidden=kind!=='new'});
$('#review-list').addEventListener('click',e=>{const b=e.target.closest('.propose');if(!b)return;const c=b.closest('.review-card');const f=state.files.find(x=>x.id===c.dataset.file);if(!f||f.folder!=='기타')return;const kind=c.querySelector('.decision').value;let dest='',rule='';if(kind==='existing'){dest=state.folders.find(x=>x.id===c.querySelector('.destination').value)?.name||'';if(!dest)return}else if(kind==='new'){dest=c.querySelector('.new-name').value.trim();rule=c.querySelector('.new-rule').value.trim();if(!dest||!rule){alert('새 폴더 이름과 지침을 입력해 주세요.');return}if(state.folders.some(x=>x.name===dest)){alert('같은 이름의 폴더가 있습니다. 기존 폴더를 선택해 주세요.');return}}openDialog({type:'review',fileId:f.id,kind,dest,rule})});
function snapshot(){return JSON.stringify({folders:state.folders,files:state.files,settings:state.settings})}
function record(title,detail,before){state.journal.unshift({id:crypto.randomUUID(),title,detail,at:new Date().toLocaleString('ko-KR'),before,undone:false});save()}
function renderTrash(){const scheduled=state.files.filter(f=>f.deleteAt&&!f.deleted);$('#scheduled-list').innerHTML=scheduled.length?scheduled.map(f=>`${fileRow(f)}<div class="journal-row"><span>삭제 사유: ${escapeHTML(f.deleteReason||'사용자 선택')}</span><button data-complete="${escapeHTML(f.id)}">삭제 완료로 표시</button></div>`).join(''):empty('삭제 예정 파일이 없습니다.');const deleted=state.files.filter(f=>f.deleted);$('#deleted-list').innerHTML=deleted.length?deleted.map(fileRow).join(''):empty('삭제 완료 파일이 없습니다.');$('#journal-list').innerHTML=state.journal.length?state.journal.map((j,i)=>`<div class="journal-row"><div><b>${escapeHTML(j.title)}</b><small>${escapeHTML(j.detail)} · ${escapeHTML(j.at)}${j.undone?' · 되돌림':''}</small></div>${i===0&&!j.undone?`<button data-undo="${escapeHTML(j.id)}">되돌리기</button>`:''}</div>`).join(''):empty('아직 처리 기록이 없습니다.')}
$('#scheduled-list').addEventListener('click',e=>{const b=e.target.closest('[data-complete]');if(b)openDialog({type:'complete',fileId:b.dataset.complete})});$('#journal-list').addEventListener('click',e=>{const b=e.target.closest('[data-undo]');if(b)openDialog({type:'undo',journalId:b.dataset.undo})});
function renderSettings(){$('#screenshot-mode').value=state.settings.screenshot;$('#deletion-days').value=String(state.settings.deletion);$('#question-interval').value=state.settings.interval}for(const [id,key] of [['screenshot-mode','screenshot'],['deletion-days','deletion'],['question-interval','interval']])document.getElementById(id).addEventListener('change',e=>{state.settings[key]=key==='deletion'?Number(e.target.value):e.target.value;save()});
function openDialog(action){pendingAction=action;lastFocus=document.activeElement;const f=state.files.find(x=>x.id===action.fileId);let body='';if(action.type==='review'){const label=action.kind==='delete'?'삭제 예정으로 이동':`${action.dest} 폴더로 분류`;body=`<p>이 파일 하나에만 다음 결정을 적용합니다.</p><dl><dt>파일</dt><dd>${escapeHTML(f.name)}</dd><dt>처리</dt><dd>${escapeHTML(label)}</dd>${action.kind==='new'?`<dt>새 지침</dt><dd>${escapeHTML(action.rule)}</dd>`:''}${action.kind==='delete'?`<dt>예정일</dt><dd>${addDays(state.settings.deletion)} · ${state.settings.deletion}일 유예</dd>`:''}</dl><p>실제 파일은 이동하거나 삭제하지 않습니다.</p>`}else if(action.type==='complete'){body=`<p>‘${escapeHTML(f.name)}’을 데모의 삭제 완료 목록으로 옮깁니다. 실제 파일은 삭제되지 않습니다.</p>`}else if(action.type==='undo'){const j=state.journal.find(x=>x.id===action.journalId);body=`<p>‘${escapeHTML(j?.title||'')}’ 결정을 되돌립니다. 가장 최근 결정만 되돌릴 수 있습니다.</p>`}else{body='<p>이 브라우저의 데모 데이터를 초기 상태로 돌립니다.</p>'}$('#dialog-body').innerHTML=body;$('#dialog-backdrop').hidden=false;$('#dialog-confirm').focus()}
function closeDialog(){$('#dialog-backdrop').hidden=true;pendingAction=null;lastFocus?.focus()}
$('#dialog-close').addEventListener('click',closeDialog);$('#dialog-cancel').addEventListener('click',closeDialog);$('#dialog-backdrop').addEventListener('click',e=>{if(e.target.id==='dialog-backdrop')closeDialog()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#dialog-backdrop').hidden)closeDialog();else closeMenu()}});
$('#dialog-confirm').addEventListener('click',()=>{const a=pendingAction;if(!a)return;if(a.type==='reset'){state=seed();activeFolder=state.folders[0].id;save();closeDialog();page('home');return}if(a.type==='undo'){const j=state.journal[0];if(j?.id!==a.journalId||j.undone)return;const old=JSON.parse(j.before);state.files=old.files;state.folders=old.folders;state.settings=old.settings;j.undone=true;save();closeDialog();render();return}const f=state.files.find(x=>x.id===a.fileId);if(!f)return;const before=snapshot();if(a.type==='complete'){f.deleted=true;f.deletedAt=today();record('삭제 완료 표시',f.name,before)}else if(a.kind==='delete'){f.deleteAt=addDays(state.settings.deletion);f.deleteReason='사용자가 분류 대기에서 삭제를 선택함';record('삭제 예정 등록',`${f.name} · ${f.deleteAt}`,before)}else{if(a.kind==='new'){state.folders.push({id:crypto.randomUUID(),name:a.dest,rule:a.rule});activeFolder=state.folders.at(-1).id}f.folder=a.dest;f.reason='사용자가 분류 대기에서 승인한 데모 결과입니다.';f.date=today();record(a.kind==='new'?'새 폴더 생성 및 분류':'기존 폴더로 분류',`${f.name} → ${a.dest}`,before)}closeDialog();render()});
$('#reset-demo').addEventListener('click',()=>openDialog({type:'reset'}));render();if(location.hash&&document.getElementById(location.hash.slice(1))?.classList.contains('page'))page(location.hash.slice(1));
